#!/usr/bin/env bash
# Q1 upgrade bundle 3: faithful MUR-momentum + REFRAIN-SWUCB baselines,
# generation-seed aggregator, AIME24 benchmark + avg@8 queue.
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing Q1 upgrade bundle 3..."
decode "scripts/ntc_w1_stats.py" << 'B64EOF'

B64EOF
decode "scripts/ntc_genseed_agg.py" << 'B64EOF'

B64EOF
decode "apply_aime_patch.py" << 'B64EOF'

B64EOF
decode "run_queue_aime.sh" << 'B64EOF'

B64EOF
python apply_aime_patch.py && rm apply_aime_patch.py
chmod +x run_queue_aime.sh
echo ""
echo "Installed. When the seed-43/44 jobs finish:"
echo "  # gen-seed aggregate (the Q1 rigor table), e.g. MATH-500 4B:"
echo "  python scripts/ntc_genseed_agg.py \\"
echo "    --probes experiments/ntc/w1_math500_Qwen3-4B.json \\"
echo "    --probes experiments/ntc/w1_math500_Qwen3-4B_s43.json \\"
echo "    --probes experiments/ntc/w1_math500_Qwen3-4B_s44.json \\"
echo "    --tag math500_Qwen3-4B"
echo "  # AIME24 avg@8 (queue when ready):"
echo "  bash run_queue_aime.sh --dry && bash run_queue_aime.sh"